import React, { useEffect, useState } from 'react';
import axios from 'axios';

const QualitySelector = ({ livestreamId, playerRef, onQualityChange }) => {
  const [qualities, setQualities] = useState([]);
  const [selectedQuality, setSelectedQuality] = useState('auto');
  const [isOpen, setIsOpen] = useState(false);
  const apiBase = '';

  useEffect(() => {
    if (!livestreamId) return;
    fetchQualities();
  }, [livestreamId]);

  // Load saved quality preference
  useEffect(() => {
    const saved = localStorage.getItem('preferredQuality');
    if (saved) setSelectedQuality(saved);
  }, []);

  const fetchQualities = async () => {
    try {
      const res = await axios.get(`${apiBase}/api/videoQualities/livestream/${livestreamId}`);
      setQualities(res.data);
    } catch (err) {
      console.error('Failed to fetch qualities:', err);
    }
  };

  const handleQualityChange = (quality) => {
    setSelectedQuality(quality);
    localStorage.setItem('preferredQuality', quality);
    setIsOpen(false);

    // Update player quality if available
    if (playerRef?.current) {
      // Notify parent component to change quality
      if (onQualityChange) {
        onQualityChange(quality);
      }

      // For HLS players, switch quality variant
      if (playerRef.current.hls) {
        if (quality === 'auto') {
          playerRef.current.hls.autoLevelCapping = -1;
        } else {
          const qualityObj = qualities.find(q => q.qualityLabel === quality);
          if (qualityObj) {
            const level = playerRef.current.hls.levels.findIndex(
              l => l.url === qualityObj.hlsUrl
            );
            if (level !== -1) {
              playerRef.current.hls.nextLevel = level;
            }
          }
        }
      }
    }
  };

  const getQualityLabel = () => {
    if (selectedQuality === 'auto') return 'Auto';
    const quality = qualities.find(q => q.qualityLabel === selectedQuality);
    return quality ? quality.qualityLabel : 'Auto';
  };

  if (qualities.length === 0) {
    return null;
  }

  return (
    <div className="relative">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="px-3 py-1 bg-white/10 hover:bg-white/20 rounded text-white text-sm font-semibold transition flex items-center gap-1"
      >
        <span>⚙️</span>
        {getQualityLabel()}
        <span className="text-xs">▼</span>
      </button>

      {isOpen && (
        <div className="absolute right-0 mt-2 w-40 bg-[#1F1F1F] border border-white/10 rounded-lg shadow-lg z-50">
          <div className="p-2 space-y-1">
            {/* Auto Option */}
            <button
              onClick={() => handleQualityChange('auto')}
              className={`w-full px-3 py-2 rounded text-left text-sm transition ${
                selectedQuality === 'auto'
                  ? 'bg-blue-600 text-white'
                  : 'hover:bg-white/10 text-gray-300'
              }`}
            >
              🔄 Auto (Recommended)
            </button>

            {/* Quality Options */}
            {qualities.map((quality) => (
              <button
                key={quality.id}
                onClick={() => handleQualityChange(quality.qualityLabel)}
                className={`w-full px-3 py-2 rounded text-left text-sm transition flex justify-between items-center ${
                  selectedQuality === quality.qualityLabel
                    ? 'bg-blue-600 text-white'
                    : 'hover:bg-white/10 text-gray-300'
                }`}
              >
                <span>{quality.qualityLabel}</span>
                <span className="text-xs opacity-70">{quality.bitrate} kbps</span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default QualitySelector;

import { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { X, Loader2, Save, Upload } from 'lucide-react';

export default function CustomizeChannelModal({ isOpen, onClose, channelData, onSaveSuccess }) {
  const [formData, setFormData] = useState({
    channelName: '',
    handle: '',
    description: '',
    bannerUrl: '',
    avatarUrl: ''
  });

  const [avatarFile, setAvatarFile] = useState(null);
  const [bannerFile, setBannerFile] = useState(null);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const avatarInputRef = useRef(null);
  const bannerInputRef = useRef(null);

  useEffect(() => {
    if (channelData) {
      setFormData({
        channelName: channelData.channelName || '',
        handle: channelData.handle || '',
        description: channelData.description || '',
        bannerUrl: channelData.bannerUrl || '',
        avatarUrl: channelData.avatarUrl || ''
      });
      setAvatarFile(null);
      setBannerFile(null);
    }
  }, [channelData, isOpen]);

  if (!isOpen) return null;

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleFileChange = (e, type) => {
    const file = e.target.files[0];
    if (file) {
      const previewUrl = URL.createObjectURL(file);
      if (type === 'avatar') {
        setAvatarFile(file);
        setFormData(prev => ({ ...prev, avatarUrl: previewUrl }));
      } else {
        setBannerFile(file);
        setFormData(prev => ({ ...prev, bannerUrl: previewUrl }));
      }
    }
  };

  const uploadFile = async (file, type = 'image') => {
    const fd = new FormData();
    fd.append('file', file);
    const res = await axios.post(`/api/upload/${type}`, fd, {
      headers: { 'Content-Type': 'multipart/form-data' }
    });
    return res.data.url;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      let finalAvatarUrl = formData.avatarUrl;
      let finalBannerUrl = formData.bannerUrl;

      // Upload if there are new files
      if (avatarFile) {
        finalAvatarUrl = await uploadFile(avatarFile, 'image');
      }
      if (bannerFile) {
        finalBannerUrl = await uploadFile(bannerFile, 'image');
      }

      const updatedData = {
        ...formData,
        avatarUrl: finalAvatarUrl,
        bannerUrl: finalBannerUrl
      };

      await axios.put(`/api/channels/${channelData.id}`, updatedData);

      // Update local storage if handle or avatar changed
      if (updatedData.handle !== localStorage.getItem('handle')) {
        localStorage.setItem('handle', updatedData.handle);
      }
      if (updatedData.avatarUrl !== localStorage.getItem('avatar')) {
        localStorage.setItem('avatar', updatedData.avatarUrl);
      }

      onSaveSuccess(updatedData.handle);
      onClose();
    } catch (err) {
      setError(err.response?.data?.message || 'Có lỗi xảy ra khi cập nhật thông tin.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/80 backdrop-blur-sm"
        onClick={onClose}
      ></div>

      {/* Modal */}
      <div className="relative w-full max-w-3xl bg-[#1A1A1A] border border-white/10 rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-white/10 shrink-0">
          <h2 className="text-xl font-bold text-white">Tùy chỉnh kênh</h2>
          <button 
            onClick={onClose}
            className="text-gray-400 hover:text-white transition-colors cursor-pointer"
          >
            <X className="w-6 h-6" />
          </button>
        </div>

        {/* Form Body */}
        <div className="p-6 overflow-y-auto flex-1 custom-scrollbar">
          {error && (
            <div className="bg-red-500/10 border border-red-500/50 text-red-500 text-sm p-3 rounded-lg mb-6">
              {error}
            </div>
          )}

          <div className="flex flex-col gap-8">
            {/* Live Preview Area */}
            <div>
              <h3 className="text-sm font-medium text-gray-300 mb-3">Xem trước (Preview)</h3>
              <div className="border border-white/10 rounded-2xl overflow-hidden bg-[#0F0F0F]">
                {/* Banner Preview */}
                <div className="w-full h-32 md:h-40 bg-[#2A2A2A] relative">
                  {formData.bannerUrl ? (
                    <img 
                      src={formData.bannerUrl} 
                      alt="Banner Preview" 
                      className="w-full h-full object-cover"
                      onError={(e) => { e.target.src = 'https://via.placeholder.com/1200x400?text=L%E1%BB%97i+t%E1%BA%A3i+%E1%BA%A3nh'; }}
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-gray-500 text-sm">Chưa có ảnh bìa</div>
                  )}
                  <div className="absolute inset-0 bg-gradient-to-t from-[#0F0F0F] via-transparent to-transparent opacity-80"></div>
                </div>

                {/* Avatar and Name Preview */}
                <div className="px-6 pb-6 -mt-10 relative z-10 flex items-end gap-4">
                  <div className="w-20 h-20 md:w-24 md:h-24 rounded-full border-4 border-[#0F0F0F] overflow-hidden bg-[#2A2A2A] shrink-0">
                    {formData.avatarUrl ? (
                      <img 
                        src={formData.avatarUrl} 
                        alt="Avatar Preview" 
                        className="w-full h-full object-cover"
                        onError={(e) => { e.target.src = 'https://via.placeholder.com/150?text=L%E1%BB%97i+%E1%BA%A3nh'; }}
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-gray-500 text-xs text-center">Chưa có<br/>avatar</div>
                    )}
                  </div>
                  <div className="flex-1 pb-1">
                    <h4 className="text-lg font-bold text-white line-clamp-1">{formData.channelName || 'Tên kênh'}</h4>
                    <p className="text-gray-400 text-sm">{formData.handle || '@handle'}</p>
                  </div>
                </div>
              </div>
            </div>

            {/* Input Form */}
            <form id="customize-form" onSubmit={handleSubmit} className="space-y-5">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="space-y-1.5">
                  <label className="text-sm font-medium text-gray-300">Tên kênh</label>
                  <input 
                    type="text" name="channelName" required
                    value={formData.channelName} onChange={handleChange}
                    className="w-full bg-[#2A2A2A] border border-transparent rounded-xl py-2.5 px-4 text-white focus:outline-none focus:border-[#FF8A65]/50 transition-colors"
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-sm font-medium text-gray-300">Tên định danh (Handle)</label>
                  <input 
                    type="text" name="handle" required
                    value={formData.handle} onChange={handleChange}
                    className="w-full bg-[#2A2A2A] border border-transparent rounded-xl py-2.5 px-4 text-white focus:outline-none focus:border-[#FF8A65]/50 transition-colors"
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="space-y-1.5">
                  <label className="text-sm font-medium text-gray-300 block mb-1">Ảnh Đại Diện (Avatar)</label>
                  <input 
                    type="file" accept="image/*" className="hidden" ref={avatarInputRef}
                    onChange={(e) => handleFileChange(e, 'avatar')}
                  />
                  <button 
                    type="button" onClick={() => avatarInputRef.current?.click()}
                    className="w-full bg-[#2A2A2A] hover:bg-[#333333] border border-white/10 rounded-xl py-2.5 px-4 text-white flex items-center justify-center gap-2 transition-colors cursor-pointer"
                  >
                    <Upload className="w-4 h-4" /> Tải ảnh lên từ máy
                  </button>
                </div>
                <div className="space-y-1.5">
                  <label className="text-sm font-medium text-gray-300 block mb-1">Ảnh Bìa (Banner)</label>
                  <input 
                    type="file" accept="image/*" className="hidden" ref={bannerInputRef}
                    onChange={(e) => handleFileChange(e, 'banner')}
                  />
                  <button 
                    type="button" onClick={() => bannerInputRef.current?.click()}
                    className="w-full bg-[#2A2A2A] hover:bg-[#333333] border border-white/10 rounded-xl py-2.5 px-4 text-white flex items-center justify-center gap-2 transition-colors cursor-pointer"
                  >
                    <Upload className="w-4 h-4" /> Tải ảnh lên từ máy
                  </button>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-sm font-medium text-gray-300">Mô tả kênh (Bio)</label>
                <textarea 
                  name="description" rows="4"
                  value={formData.description} onChange={handleChange}
                  placeholder="Giới thiệu đôi nét về bạn..."
                  className="w-full bg-[#2A2A2A] border border-transparent rounded-xl py-2.5 px-4 text-white focus:outline-none focus:border-[#FF8A65]/50 transition-colors resize-none"
                ></textarea>
              </div>
            </form>
          </div>
        </div>

        {/* Footer */}
        <div className="p-6 border-t border-white/10 shrink-0 flex justify-end gap-3 bg-[#1A1A1A]">
          <button 
            type="button" onClick={onClose}
            className="px-6 py-2.5 rounded-full font-medium text-white hover:bg-[#2A2A2A] transition-colors cursor-pointer"
          >
            Hủy
          </button>
          <button 
            type="submit" form="customize-form" disabled={loading}
            className="px-6 py-2.5 bg-[#FF5722] hover:bg-[#E64A19] text-white rounded-full font-medium flex items-center gap-2 transition-colors disabled:opacity-70 cursor-pointer"
          >
            {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5" />}
            Lưu thay đổi
          </button>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { Music, Monitor, Gamepad2, Tv, BookOpen, Dumbbell, LayoutGrid, Flame, ChevronRight, Clapperboard, Coffee } from 'lucide-react';

import * as LucideIcons from 'lucide-react';
import { getIconColor } from '../../utils/iconHelpers';

export const DEFAULT_CATEGORY_ICON = { icon: 'LayoutGrid', iconColor: 'text-gray-400', bg: 'bg-white/10' };

export default function CategoryFilter({ onSelect }) {
  const [categories, setCategories] = useState([]);
  const [activeCategory, setActiveCategory] = useState(0);
  const scrollRef = useRef(null);

  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const response = await axios.get('/api/videos/categories');
        setCategories([{ id: 0, name: 'Tất cả', icon: 'Flame' }, ...response.data]);
      } catch (err) {
        console.error('Failed to fetch categories:', err);
      }
    };
    fetchCategories();
  }, []);

  if (categories.length === 0) return null;

  const handleSelect = (id) => {
    setActiveCategory(id);
    onSelect?.(id);
  };

  const scrollRight = () => {
    scrollRef.current?.scrollBy({ left: 240, behavior: 'smooth' });
  };

  return (
    <div>
      {/* Header */}
      {/* <h3 className="text-white font-bold text-sm mb-3">Khám phá theo danh mục</h3> */}

      {/* Scrollable row + arrow */}
      <div className="relative flex items-center pt-5">
        <div
          ref={scrollRef}
          className="flex items-center gap-2 overflow-x-auto scrollbar-hide pr-10"
        >
          {categories.map((category) => {
            const isActive = activeCategory === category.id;
            const IconComponent = LucideIcons[category.icon] || LucideIcons.LayoutGrid;

            const iconColor = getIconColor(category.icon);

            return (
              <button
                key={category.id}
                onClick={() => handleSelect(category.id)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-xl whitespace-nowrap text-sm font-medium transition-all cursor-pointer shrink-0 border ${
                  isActive
                    ? 'bg-[#FF5722]/15 border-[#FF5722]/40 text-white'
                    : 'bg-transparent border-white/10 text-gray-300 hover:border-white/30 hover:text-white'
                }`}
              >
                {/* Icon box */}
                <span className={`w-6 h-6 flex items-center justify-center`}>
                  <IconComponent className={`w-5 h-5 ${iconColor}`} />
                </span>
                {category.name}
              </button>
            );
          })}
        </div>

        {/* Scroll arrow */}
        <button
          onClick={scrollRight}
          className="absolute right-0 w-8 h-8 bg-[#1A1A1A] hover:bg-[#272727] border border-white/10 rounded-full flex items-center justify-center text-gray-400 hover:text-white transition-colors cursor-pointer shrink-0 shadow-lg"
        >
          <ChevronRight className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}

import { Play, Plus, CheckCircle, Flame } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { useState } from 'react';
import SaveToPlaylistDropdown from '../video/SaveToPlaylistDropdown';

const formatViews = (v) => {
  if (!v) return '0';
  if (v >= 1_000_000) return (v / 1_000_000).toFixed(1).replace(/\.0$/, '') + ' Tr';
  if (v >= 1_000) return (v / 1_000).toFixed(1).replace(/\.0$/, '') + ' N';
  return String(v);
};

const timeAgo = (d) => {
  if (!d) return '';
  const s = Math.floor((Date.now() - new Date(d)) / 1000);
  if (s >= 31536000) return Math.floor(s / 31536000) + ' năm trước';
  if (s >= 2592000)  return Math.floor(s / 2592000)  + ' tháng trước';
  if (s >= 86400)    return Math.floor(s / 86400)    + ' ngày trước';
  if (s >= 3600)     return Math.floor(s / 3600)     + ' giờ trước';
  if (s >= 60)       return Math.floor(s / 60)       + ' phút trước';
  return 'Vừa xong';
};

export default function FeaturedHero({ video, totalSlides = 4, currentSlide = 0, onNext, onPrev }) {
  const navigate = useNavigate();
  const [showPlaylistDropdown, setShowPlaylistDropdown] = useState(false);
  if (!video) return null;

  // Split title to add gradient to middle parts
  const words = (video.title || '').split(' ');
  const third = Math.max(1, Math.floor(words.length / 3));
  const part1 = words.slice(0, third).join(' ');
  const part2 = words.slice(third, Math.max(third * 2, words.length - 1)).join(' ');
  const part3 = words.slice(Math.max(third * 2, words.length - 1)).join(' ');

  return (
    <div
      onClick={(e) => {
        if (e.target.closest('a') || e.target.closest('button')) return;
        navigate(video.isShort ? `/shorts?id=${video.id}` : `/watch/${video.id}`);
      }}
      className="relative w-full h-[480px] md:h-[520px] rounded-3xl group cursor-pointer select-none"
    >
      {/* Background container with overflow-hidden */}
      <div className="absolute inset-0 rounded-3xl overflow-hidden">
        {/* Thumbnail */}
        <img
          src={video.thumbnailUrl || 'https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=1400&q=80'}
          alt={video.title}
          className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
        />

        {/* Gradient overlays */}
        <div className="absolute inset-0 bg-gradient-to-r from-[#0f0f1a]/95 via-[#0f0f1a]/70 to-transparent" />
        <div className="absolute inset-0 bg-gradient-to-t from-[#0f0f1a] via-transparent to-transparent opacity-80" />
      </div>

      {/* Arrow right */}
      <button
        onClick={(e) => { e.stopPropagation(); onNext?.(); }}
        className="absolute right-6 top-1/2 -translate-y-1/2 w-10 h-10 bg-black/20 hover:bg-black/40 rounded-full flex items-center justify-center backdrop-blur-md transition-all z-10 border border-white/10"
      >
        <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" />
        </svg>
      </button>

      {/* Content — left side, vertically centered */}
      <div className="absolute inset-y-0 left-0 flex flex-col justify-center p-8 md:p-12 max-w-[65%] z-10">
        {/* Badge */}
        <div className="inline-flex items-center gap-1.5 bg-[#FF5722] text-white text-[11px] font-bold px-3 py-1.5 rounded-full mb-5 uppercase tracking-wider w-fit shadow-lg shadow-[#FF5722]/30">
          <Flame className="w-3.5 h-3.5" />
          Đề xuất
        </div>

        {/* Title — large with gradient highlight on middle part */}
        <h2 className="text-3xl md:text-5xl font-extrabold text-white leading-[1.2] mb-5 drop-shadow-lg">
          {part1 && <span>{part1} </span>}
          {part2 && (
            <span className="bg-gradient-to-r from-pink-400 via-[#FF5722] to-orange-400 bg-clip-text text-transparent">
              {part2}{' '}
            </span>
          )}
          {part3 && <span>{part3}</span>}
        </h2>

        {/* Description */}
        <p className="text-gray-300 text-[15px] leading-relaxed mb-6 line-clamp-2 max-w-lg">
          {video.description || 'Tuyển chọn những ca khúc nổi bật nhất đang làm mưa làm gió trên mọi bảng xếp hạng.'}
        </p>

        {/* Channel info */}
        <div className="flex items-center gap-2 mb-8 flex-wrap">
          <Link
            to={`/c/${video.channelHandle}`}
            onClick={e => e.stopPropagation()}
            className="flex items-center gap-2 hover:opacity-90 transition-opacity"
          >
            {video.channelAvatarUrl ? (
              <img src={video.channelAvatarUrl} alt="" className="w-8 h-8 rounded-full object-cover ring-2 ring-white/10" />
            ) : (
              <div className="w-8 h-8 rounded-full bg-gradient-to-br from-[#FF5722] to-[#9C27B0] flex items-center justify-center text-white text-[12px] font-bold">
                {(video.channelName || 'A')[0].toUpperCase()}
              </div>
            )}
            <span className="text-white font-semibold text-[15px] ml-1">{video.channelName}</span>
             <CheckCircle className="w-3 h-3 text-white fill-green-500 shrink-0" />
          </Link>

          <span className="text-gray-600 text-xs mx-1.5">•</span>

          {/* Inline play icon and views */}
          <div className="w-6 h-6 rounded-full bg-[#FF5722] flex items-center justify-center shadow-md shadow-[#FF5722]/30">
            <Play className="w-3 h-3 fill-white text-white ml-0.5" />
          </div>

          <span className="text-gray-300 text-[13px] ml-1">{formatViews(video.viewsCount)} lượt xem</span>
          <span className="text-gray-600 text-xs mx-1.5">•</span>
          <span className="text-gray-300 text-[13px]">{timeAgo(video.createdAt)}</span>
        </div>

        {/* CTA Buttons */}
        <div className="flex items-center gap-4 flex-wrap relative">
          <button
            onClick={(e) => { e.stopPropagation(); navigate(video.isShort ? `/shorts?id=${video.id}` : `/watch/${video.id}`); }}
            className="flex items-center gap-2 bg-gradient-to-r from-[#FF5722] to-[#E91E63] hover:opacity-90 active:scale-95 text-white font-bold text-[15px] px-8 py-3 rounded-full transition-all shadow-lg shadow-[#FF5722]/30 cursor-pointer"
          >
            <Play className="w-5 h-5 fill-white" />
            Xem ngay
          </button>

          <div className="relative">
            <button
              onClick={e => { e.stopPropagation(); setShowPlaylistDropdown(!showPlaylistDropdown); }}
              className="flex items-center gap-2 bg-black/40 hover:bg-black/60 backdrop-blur-md active:scale-95 text-gray-200 hover:text-white font-medium text-[15px] px-6 py-3 rounded-full transition-all border border-white/10 cursor-pointer"
            >
              <Plus className="w-5 h-5" />
              Danh sách phát
            </button>

            {showPlaylistDropdown && (
              <div 
                className="absolute top-full left-0 mt-2 z-50 min-w-[250px]"
                onClick={e => e.stopPropagation()}
              >
                <SaveToPlaylistDropdown 
                  videoId={video.id} 
                  onClose={() => setShowPlaylistDropdown(false)} 
                />
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Slide dots — bottom right */}
      <div className="absolute bottom-6 right-8 flex gap-2 z-10">
        {Array.from({ length: totalSlides }).map((_, i) => (
          <span
            key={i}
            className={`block rounded-full transition-all duration-300 ${
              i === currentSlide ? 'w-6 h-1.5 bg-[#FF5722]' : 'w-1.5 h-1.5 bg-white/40'
            }`}
          />
        ))}
      </div>
    </div>
  );
}

