              <>
                <UploadCloud className="w-10 h-10 text-gray-400 mb-3" />
                <p className="text-white text-sm font-medium mb-1">Kéo và thả video vào đây</p>
                <p className="text-gray-500 text-xs mb-4">hoặc</p>
