        </div>

        {/* Trạng thái hiển thị */}
        <div>
          <label className="block text-white text-sm font-medium mb-1">Trạng thái hiển thị *</label>
          <p className="text-gray-400 text-xs mb-3">Chọn ai có thể xem video này</p>
