             ) : thumbnailPreview ? (
                <img src={thumbnailPreview} className="w-full h-full object-cover" />
             ) : (
                <div className="w-full h-full flex flex-col items-center justify-center bg-white/5">
                  <PlaySquare className="w-12 h-12 text-gray-600 mb-2" />
