            <div className="flex justify-between text-xs">
              <span className="text-gray-400 flex items-center gap-2"><HardDrive className="w-4 h-4"/> Kích thước</span>
              <span className="text-white">{videoFile ? (videoFile.size / (1024 * 1024)).toFixed(2) + ' MB' : '-'}</span>
            </div>
            <div className="flex justify-between text-xs">
              <span className="text-gray-400 flex items-center gap-2"><FileCode className="w-4 h-4"/> Tệp video</span>
              <span className="text-white truncate max-w-[150px]">{videoFile ? videoFile.name : '-'}</span>
            </div>
            <div className="flex justify-between text-xs">
              <span className="text-gray-400 flex items-center gap-2"><ImageIcon className="w-4 h-4"/> Tệp ảnh thu nhỏ</span>
              <span className="text-white truncate max-w-[150px]">{thumbnailFile ? thumbnailFile.name : '-'}</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function DeleteVideoModal({ video, onClose, onSuccess }) {
  const [isDeleting, setIsDeleting] = useState(false);
  const [error, setError] = useState('');
  const [isConfirmed, setIsConfirmed] = useState(false);

  const handleDelete = async () => {
    setIsDeleting(true);
    setError('');
    try {
      const token = localStorage.getItem('token');
      await axios.delete(`/api/videos/${video.id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      onSuccess();
    } catch (err) {
      setError(err.response?.data?.message || 'Có lỗi xảy ra khi xóa video.');
      setIsDeleting(false);
    }
  };

  if (!video) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
      <div className="bg-[#212121] rounded-2xl max-w-md w-full border border-white/10 shadow-2xl p-6 animate-in fade-in zoom-in-95 duration-200">
        <div className="flex items-start gap-4 mb-6">
          <div className="w-12 h-12 rounded-full bg-red-500/10 flex items-center justify-center shrink-0">
            <Trash2 className="w-6 h-6 text-red-500" />
          </div>
          <div className="flex-1">
            <h3 className="text-xl font-bold text-white mb-2">Xóa video này?</h3>
            <p className="text-gray-400 text-sm leading-relaxed mb-3">
              Bạn đang chuẩn bị xóa video:
            </p>
          </div>
        </div>
        <div className="flex gap-3 p-2 rounded-lg">
          <div className="w-24 h-14 rounded overflow-hidden shrink-0 bg-black/50">
            <img src={video.thumbnailUrl || 'https://via.placeholder.com/600x400?text=No+Thumbnail'} alt={video.title} className="w-full h-full object-cover" />
          </div>
          <strong className="text-white text-sm line-clamp-2 mt-1">{video.title}</strong>
        </div>
        <br/>

        <div className="bg-[#1A1A1A] p-4 rounded-xl border border-white/5 mb-6">
          <div className="flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-yellow-500 shrink-0 mt-0.5" />
            <div className="text-sm text-gray-300">
              <p className="font-medium text-white mb-1">Lưu ý quan trọng:</p>
              <ul className="list-disc pl-4 space-y-1 text-gray-400">
                <li>Video sẽ bị xóa vĩnh viễn khỏi nền tảng.</li>
                <li>Toàn bộ lượt xem, lượt thích và bình luận sẽ bị mất.</li>
                <li>Hành động này không thể hoàn tác!</li>
              </ul>
            </div>
          </div>
        </div>

        <div className="mb-6 flex items-start gap-3">
          <input 
            type="checkbox" 
            id="confirmDelete" 
            checked={isConfirmed} 
            onChange={(e) => setIsConfirmed(e.target.checked)} 
            className="w-4 h-4 mt-0.5 accent-red-600 cursor-pointer shrink-0"
          />
          <label htmlFor="confirmDelete" className="text-gray-300 text-sm cursor-pointer select-none">
            Tôi đã hiểu rằng hành động này không thể hoàn tác và xác nhận xóa video.
          </label>
        </div>

        {error && <div className="mb-4 text-red-500 text-sm bg-red-500/10 p-3 rounded-lg border border-red-500/20">{error}</div>}

        <div className="flex justify-end gap-3">
          <button 
            onClick={onClose}
            disabled={isDeleting}
            className="px-5 py-2.5 rounded-xl bg-white/5 hover:bg-white/10 text-white font-medium transition-colors cursor-pointer disabled:opacity-50"
          >
            Hủy
          </button>
          <button 
            onClick={handleDelete}
            disabled={isDeleting || !isConfirmed}
            className="px-5 py-2.5 rounded-xl bg-red-600 hover:bg-red-700 text-white font-medium transition-colors flex items-center gap-2 cursor-pointer disabled:opacity-50"
          >
            {isDeleting ? <Loader2 className="w-4 h-4 animate-spin" /> : null}
            Xóa vĩnh viễn
          </button>
        </div>
      </div>
    </div>
  );
}

