import { useEffect, useState } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import { CheckCircle2, XCircle, ArrowRight, Video } from 'lucide-react';
import { toast } from 'react-toastify';

export default function PaymentResult() {
  const [searchParams] = useSearchParams();
  const [status, setStatus] = useState('loading');
  const [amount, setAmount] = useState(0);
  const [paymentType, setPaymentType] = useState('Premium');

  useEffect(() => {
    const paymentStatus = searchParams.get('status');
    const paymentAmount = searchParams.get('amount');
    const code = searchParams.get('code');
    const type = searchParams.get('type') || 'Premium';

    if (paymentStatus === 'success') {
      setStatus('success');
      setAmount(Number(paymentAmount));
      setPaymentType(type);
      toast.success(type === 'Membership' ? 'Thanh toán hội viên thành công!' : 'Thanh toán thành công! Tài khoản của bạn đã được nâng cấp.');
    } else {
      setStatus('failed');
      if (code === '24') {
        toast.error('Giao dịch đã bị huỷ.');
      } else {
        toast.error('Giao dịch thất bại hoặc có lỗi xảy ra.');
      }
    }
  }, [searchParams]);

  return (
    <div className="min-h-[80vh] flex items-center justify-center bg-[#0A0A0B] px-4">
      <div className="max-w-md w-full bg-[#1A1A1A] rounded-3xl p-8 border border-white/10 shadow-2xl text-center">
        {status === 'loading' && (
          <div className="animate-pulse flex flex-col items-center">
            <div className="w-20 h-20 bg-gray-700 rounded-full mb-6"></div>
            <div className="h-6 bg-gray-700 rounded w-1/2 mb-4"></div>
            <div className="h-4 bg-gray-700 rounded w-3/4"></div>
          </div>
        )}

        {status === 'success' && (
          <div className="flex flex-col items-center animate-in zoom-in duration-500">
            <div className="w-24 h-24 bg-green-500/20 rounded-full flex items-center justify-center mb-6 border border-green-500/30 shadow-[0_0_30px_rgba(34,197,94,0.3)]">
              <CheckCircle2 className="w-12 h-12 text-green-500" />
            </div>
            <h1 className="text-3xl font-bold text-white mb-2">Thanh toán thành công!</h1>
            <p className="text-gray-400 mb-6">
              Cảm ơn bạn. Số tiền {amount.toLocaleString('vi-VN')}đ đã được thanh toán. 
              {paymentType === 'Membership' 
                ? ' Bạn đã trở thành hội viên của kênh và có thể tận hưởng các đặc quyền.'
                : ' Tài khoản của bạn đã được nâng cấp lên Premium.'}
            </p>
            <Link 
              to="/" 
              className="w-full flex items-center justify-center gap-2 bg-gradient-to-r from-[#FF5722] to-[#E91E63] text-white py-3 rounded-xl font-bold hover:opacity-90 transition-opacity"
            >
              <Video className="w-5 h-5" />
              Bắt đầu xem video
            </Link>
          </div>
        )}

        {status === 'failed' && (
          <div className="flex flex-col items-center animate-in zoom-in duration-500">
            <div className="w-24 h-24 bg-red-500/20 rounded-full flex items-center justify-center mb-6 border border-red-500/30 shadow-[0_0_30px_rgba(239,68,68,0.3)]">
              <XCircle className="w-12 h-12 text-red-500" />
            </div>
            <h1 className="text-3xl font-bold text-white mb-2">Giao dịch không thành công</h1>
            <p className="text-gray-400 mb-6">
              Rất tiếc, quá trình thanh toán đã bị huỷ hoặc xảy ra lỗi. Vui lòng thử lại sau.
            </p>
            <div className="flex flex-col gap-3 w-full">
              <Link 
                to="/premium" 
                className="w-full flex items-center justify-center gap-2 bg-gradient-to-r from-gray-700 to-gray-600 text-white py-3 rounded-xl font-bold hover:opacity-90 transition-opacity"
              >
                Thử lại
              </Link>
              <Link 
                to="/" 
                className="text-gray-400 hover:text-white text-sm font-semibold transition-colors mt-2 flex items-center justify-center gap-1"
              >
                Về trang chủ <ArrowRight className="w-4 h-4" />
              </Link>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Check, X, Ban, Download, Tv, Headphones, Crown, Play, Star } from 'lucide-react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import { toast } from 'react-toastify';

export default function Premium() {
  const [isYearly, setIsYearly] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [currentPlan, setCurrentPlan] = useState('Free');
  const [currentCycle, setCurrentCycle] = useState('Monthly');
  const [premiumUntil, setPremiumUntil] = useState(null);

  React.useEffect(() => {
    const fetchPlan = async () => {
      const token = localStorage.getItem('token');
      if (token) {
        try {
          const res = await axios.get('/api/payment/current-plan', {
            headers: { Authorization: `Bearer ${token}` }
          });
          if (res.data && res.data.plan) {
            setCurrentPlan(res.data.plan);
            if (res.data.cycle) {
              setCurrentCycle(res.data.cycle);
            }
            if (res.data.premiumUntil) {
              setPremiumUntil(new Date(res.data.premiumUntil));
            }
          }
        } catch (err) {
          console.error('Failed to fetch plan:', err);
        }
      }
    };
    fetchPlan();
  }, []);

  const getPlanStatus = (targetPlan, targetIsYearly) => {
    if (currentPlan === 'Free' && targetPlan !== 'Free') return 'upgrade';
    if (currentPlan === 'Free' && targetPlan === 'Free') return 'current';

    const ranks = { 'Free': 0, 'Family': 1, 'Premium': 2 };
    const currentRank = ranks[currentPlan] || 0;
    const targetRank = ranks[targetPlan] || 0;

    if (currentRank > targetRank) return 'downgrade'; 
    if (currentRank < targetRank) return 'upgrade'; 

    const currentCycleRank = currentCycle === 'Yearly' ? 1 : 0;
    const targetCycleRank = targetIsYearly ? 1 : 0;

    if (currentCycleRank > targetCycleRank) return 'downgrade';
    if (currentCycleRank < targetCycleRank) return 'upgrade';

    return 'current'; 
  };

  const handlePayment = async (plan, amount) => {
    const token = localStorage.getItem('token');
    if (!token) {
      toast.error('Vui lòng đăng nhập để thực hiện thanh toán.');
      return;
    }

    try {
      setIsLoading(true);
      const response = await axios.post(
        '/api/payment/create-payment-url',
        {
          plan,
          cycle: isYearly ? 'Yearly' : 'Monthly',
          amount
        },
        {
          headers: {
            Authorization: `Bearer ${token}`
          }
        }
      );

      if (response.data && response.data.url) {
        window.location.href = response.data.url;
      }
    } catch (error) {
      console.error(error);
      toast.error('Có lỗi xảy ra khi tạo giao dịch thanh toán.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#0A0A0B] text-white pb-20 font-sans overflow-x-hidden">
      {/* Header Section */}
      <div 
        className="relative pt-16 pb-24 overflow-hidden bg-cover bg-center bg-no-repeat"
        style={{ backgroundImage: 'url(/premium-hero.png)' }}
      >
        <div className="max-w-[1200px] mx-auto px-4 md:px-8 relative z-10">
          {/* Left Text */}
          <div className="max-w-[600px]">
            <h2 className="text-[#E91E63] font-bold text-sm tracking-widest uppercase mb-4">Nâng cấp tài khoản</h2>
            <h1 className="text-4xl md:text-5xl lg:text-6xl font-extrabold text-white leading-tight mb-6">
              Trải nghiệm VideoX <br />
              theo cách <span className="text-[#9C27B0]">của bạn</span>
            </h1>
            <p className="text-gray-400 text-base md:text-lg mb-8 max-w-[500px]">
              Chọn gói phù hợp để tận hưởng kho nội dung khổng lồ, chất lượng cao và nhiều tính năng độc quyền.
            </p>

            <div className="flex flex-wrap gap-4">
              <div className="flex items-center gap-2 bg-[#1A1A1A] border border-white/10 rounded-xl px-4 py-3">
                <div className="w-8 h-8 rounded-full bg-red-500/20 flex items-center justify-center">
                  <Ban className="w-4 h-4 text-red-500" />
                </div>
                <div>
                  <p className="text-white text-sm font-bold">Không quảng cáo</p>
                  <p className="text-gray-500 text-[10px]">Xem video liền mạch</p>
                </div>
              </div>

              <div className="flex items-center gap-2 bg-[#1A1A1A] border border-white/10 rounded-xl px-4 py-3">
                <div className="w-8 h-8 rounded-full bg-purple-500/20 flex items-center justify-center">
                  <Download className="w-4 h-4 text-purple-400" />
                </div>
                <div>
                  <p className="text-white text-sm font-bold">Tải video</p>
                  <p className="text-gray-500 text-[10px]">Xem mọi lúc, mọi nơi</p>
                </div>
              </div>

              <div className="flex items-center gap-2 bg-[#1A1A1A] border border-white/10 rounded-xl px-4 py-3">
                <div className="w-8 h-8 rounded-full bg-pink-500/20 flex items-center justify-center">
                  <Tv className="w-4 h-4 text-pink-400" />
                </div>
                <div>
                  <p className="text-white text-sm font-bold">Chất lượng cao</p>
                  <p className="text-gray-500 text-[10px]">Tối đa 4K UHD</p>
                </div>
              </div>
            </div>
          </div>
        </div>
        {/* Gradient Fade out */}
        <div className="absolute bottom-0 left-0 right-0 h-40 bg-gradient-to-t from-[#0A0A0B] to-transparent pointer-events-none" />
      </div>

      {/* Pricing Section */}
      <div className="max-w-[1500px] mx-auto px-4 md:px-4 py-4 relative z-10 mt-5">
        <h2 className="text-2xl md:text-3xl font-bold text-center text-white mb-8">Chọn gói phù hợp với bạn</h2>

        {/* Toggle */}
        <div className="flex justify-center mb-12">
