// ─── Main Shorts Page ──────────────────────────────────────────────────────────
export default function Shorts() {
  const [shorts, setShorts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeIndex, setActiveIndex] = useState(0);
  const [isMuted, setIsMuted] = useState(false);
  const [globalShowComments, setGlobalShowComments] = useState(false);
  const [loginModal, setLoginModal] = useState({ isOpen: false, message: '' });
  const containerRef = useRef(null);
  const itemRefs = useRef([]);
  const [searchParams] = useSearchParams();
  const targetId = searchParams.get('id');
  const navigate = useNavigate();

  useEffect(() => {
    const fetchShorts = async () => {
      try {
        const token = localStorage.getItem('token');
        const headers = token ? { Authorization: `Bearer ${token}` } : {};
        const res = await axios.get('/api/videos/shorts', { headers });
        let data = res.data.map(short => {
          if (!short.videoUrl || short.videoUrl.includes('example.com') || short.videoUrl.includes('commondatastorage')) {
            short.videoUrl = "https://www.w3schools.com/html/mov_bbb.mp4";
          }
          return short;
        });
        setShorts(data);
      } catch (err) {
        console.error("Error fetching shorts", err);
      } finally {
        setLoading(false);
      }
    };
    fetchShorts();
  }, []);

  // Deep-link: scroll to specific short when ?id= is provided
  useEffect(() => {
    if (!targetId || shorts.length === 0) return;
    const idx = shorts.findIndex(s => s.id === targetId);
    if (idx !== -1) {
      setTimeout(() => {
        itemRefs.current[idx]?.scrollIntoView({ behavior: 'instant' });
      }, 100);
    }
  }, [targetId, shorts]);

  // Detect active video via IntersectionObserver
  useEffect(() => {
    const container = containerRef.current;
    if (!container || shorts.length === 0) return;
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const idx = itemRefs.current.indexOf(entry.target);
            if (idx !== -1) setActiveIndex(idx);
          }
        });
      },
      { root: container, threshold: 0.6 }
    );

    // Clear and re-observe
    itemRefs.current.forEach((el) => el && observer.observe(el));

    return () => observer.disconnect();
  }, [shorts]);

  const goNext = useCallback(() => {
    if (activeIndex < shorts.length - 1)
      itemRefs.current[activeIndex + 1]?.scrollIntoView({ behavior: 'smooth' });
  }, [activeIndex, shorts.length]);
  const goPrev = useCallback(() => {
    if (activeIndex > 0)
      itemRefs.current[activeIndex - 1]?.scrollIntoView({ behavior: 'smooth' });
  }, [activeIndex]);

  // Keyboard navigation
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === 'ArrowDown') goNext();
      if (e.key === 'ArrowUp') goPrev();
      if (e.key === 'm' || e.key === 'M') setIsMuted((m) => !m);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [goNext, goPrev]);

  if (loading) return <div className="w-full h-[calc(100vh-64px)] flex items-center justify-center bg-[#0F0F0F]"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-white"></div></div>;
  if (shorts.length === 0) return <div className="w-full h-[calc(100vh-64px)] flex items-center justify-center bg-[#0F0F0F] text-white">Chưa có video ngắn nào</div>;

  return (
    <>
      <style>{`
        .shorts-scroll::-webkit-scrollbar { display: none; }
        .shorts-scroll { -ms-overflow-style: none; scrollbar-width: none; }
        @keyframes shortFlash {
          0%   { transform: scale(0.8); opacity: 1; }
          100% { transform: scale(1.5); opacity: 0; }
        }
      `}</style>

      {/* Scroll feed fills space below header */}
      <div
        ref={containerRef}
        className="shorts-scroll w-full overflow-y-scroll snap-y snap-mandatory bg-[#0F0F0F]"
        style={{ height: 'calc(100vh - 64px)' }}
      >
        {shorts.map((short, i) => (
          <div
            key={short.id}
            ref={(el) => (itemRefs.current[i] = el)}
            className="w-full snap-start snap-always"
            style={{ height: 'calc(100vh - 64px)' }}
          >
            <ShortItem
              short={short}
              isActive={i === activeIndex}
              isMuted={isMuted}
              onMuteToggle={() => setIsMuted((m) => !m)}
              showComments={globalShowComments}
              onToggleComments={() => setGlobalShowComments(prev => !prev)}
              onCloseComments={() => setGlobalShowComments(false)}
              onRequestLogin={(msg) => setLoginModal({ isOpen: true, message: msg })}
            />
          </div>
        ))}
      </div>

      {/* Navigation arrows — fixed, right side */}
      <div className={`fixed top-1/2 -translate-y-1/2 z-50 flex flex-col gap-3 pointer-events-none transition-all duration-300 ease-in-out ${globalShowComments ? 'right-[364px]' : 'right-6'}`}>
        <button
          onClick={goPrev}
          disabled={activeIndex === 0}
          className={`w-10 h-10 rounded-full flex items-center justify-center transition-all duration-200 pointer-events-auto
            ${activeIndex === 0
              ? 'bg-white/5 text-white/20 cursor-not-allowed'
              : 'bg-[#2A2A2A] text-white hover:bg-[#3A3A3A] hover:scale-110 cursor-pointer shadow-lg'
            }`}
        >
          <ChevronUp className="w-5 h-5" />
        </button>
        <button
          onClick={goNext}
          disabled={activeIndex === shorts.length - 1}
          className={`w-10 h-10 rounded-full flex items-center justify-center transition-all duration-200 pointer-events-auto
            ${activeIndex === shorts.length - 1
              ? 'bg-white/5 text-white/20 cursor-not-allowed'
              : 'bg-[#2A2A2A] text-white hover:bg-[#3A3A3A] hover:scale-110 cursor-pointer shadow-lg'
            }`}
        >
          <ChevronDown className="w-5 h-5" />
        </button>
      </div>

      {/* Login Modal */}
      {loginModal.isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <div className="bg-[#212121] rounded-2xl p-6 w-[90%] max-w-sm border border-white/10 shadow-2xl animate-in fade-in zoom-in-95 duration-200">
            <h3 className="text-xl font-bold text-white mb-2">Đăng nhập</h3>
            <p className="text-white/70 text-sm mb-6">{loginModal.message}</p>
            <div className="flex gap-3 justify-end">
              <button 
                onClick={() => setLoginModal({ isOpen: false, message: '' })}
                className="px-4 py-2 text-sm font-medium text-white/70 hover:text-white transition-colors cursor-pointer"
              >
                Hủy
              </button>
              <button 
                onClick={() => navigate('/login')}
                className="px-4 py-2 text-sm font-medium bg-[#3ea6ff] hover:bg-[#5eb7ff] text-[#0f0f0f] rounded-full transition-colors cursor-pointer"
              >
                Đăng nhập
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

import React, { useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios';

const CreatorDashboard = () => {
  const navigate = useNavigate();
  const { search } = useLocation();
  const params = new URLSearchParams(search);
  const idParam = params.get('id');

  const [livestream, setLivestream] = useState(null);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const apiBase = '';

  useEffect(() => {
    if (!idParam) {
      navigate('/studio');
      return;
    }

    const fetchData = async () => {
      try {
        // Fetch livestream info
        const liveRes = await axios.get(`${apiBase}/api/livestreams/${idParam}`);
        setLivestream(liveRes.data);

        // Fetch stats
        const statsRes = await axios.get(`${apiBase}/api/streamstatistics/livestream/${idParam}/stats?minutes=120`);
        setStats(statsRes.data);
      } catch (err) {
        console.error('Failed to fetch dashboard data:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();

    // Refresh stats every 10 seconds
    const interval = setInterval(fetchData, 10000);
    return () => clearInterval(interval);
  }, [idParam, navigate]);

  if (loading) {
    return <div className="p-6 text-white text-center">Đang tải...</div>;
  }

  if (!livestream) {
    return <div className="p-6 text-white text-center">Không tìm thấy livestream</div>;
  }

  return (
    <div className="p-6 bg-[#0F0F0F] min-h-screen">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="mb-6 flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-bold text-white mb-2">{livestream.title}</h1>
            <p className="text-gray-400">Trạng thái: <span className={`font-semibold ${livestream.status === 'live' ? 'text-red-500' : 'text-yellow-500'}`}>{livestream.status}</span></p>
          </div>
          <button onClick={() => navigate(-1)} className="px-4 py-2 bg-white/10 hover:bg-white/20 rounded text-white">
            Quay lại
          </button>
        </div>

        {/* Main Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          {/* Current Viewers */}
          <div className="bg-[#1F1F1F] p-6 rounded-lg border border-white/10">
            <div className="text-gray-400 text-sm mb-2">Người xem hiện tại</div>
            <div className="text-4xl font-bold text-blue-400">
              {stats?.currentViewers || 0}
            </div>
          </div>

          {/* Peak Viewers */}
          <div className="bg-[#1F1F1F] p-6 rounded-lg border border-white/10">
            <div className="text-gray-400 text-sm mb-2">Đỉnh cao</div>
            <div className="text-4xl font-bold text-green-400">
              {stats?.peakViewers || 0}
            </div>
          </div>

          {/* Average Viewers */}
          <div className="bg-[#1F1F1F] p-6 rounded-lg border border-white/10">
            <div className="text-gray-400 text-sm mb-2">Trung bình</div>
            <div className="text-4xl font-bold text-yellow-400">
              {stats?.avgViewers || 0}
            </div>
          </div>

          {/* Total Views */}
          <div className="bg-[#1F1F1F] p-6 rounded-lg border border-white/10">
            <div className="text-gray-400 text-sm mb-2">Tổng lượt xem</div>
            <div className="text-4xl font-bold text-purple-400">
              {livestream.totalViews || 0}
            </div>
          </div>
        </div>

        {/* Charts Section */}
        {stats && stats.stats.length > 0 && (
          <div className="bg-[#1F1F1F] p-6 rounded-lg border border-white/10 mb-6">
            <h2 className="text-xl font-bold text-white mb-4">Lượt xem theo thời gian</h2>
            
            {/* Simple Text-based Chart */}
            <div className="space-y-2">
              {stats.stats.map((stat, idx) => {
                const maxViewers = Math.max(...stats.stats.map(s => s.viewerCount));
                const barWidth = (stat.viewerCount / maxViewers) * 100;
                const time = new Date(stat.recordedAt).toLocaleTimeString();
                
                return (
                  <div key={idx} className="flex items-center gap-4">
                    <div className="text-xs text-gray-400 w-12">{time}</div>
                    <div className="flex-1 bg-white/10 h-6 rounded overflow-hidden">
                      <div
                        className="bg-gradient-to-r from-blue-500 to-blue-600 h-full transition-all"
                        style={{ width: `${barWidth}%` }}
                      />
                    </div>
                    <div className="text-sm text-white w-12 text-right">{stat.viewerCount}</div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Stream Info */}
        <div className="bg-[#1F1F1F] p-6 rounded-lg border border-white/10 mb-6">
          <h2 className="text-xl font-bold text-white mb-4">Thông tin livestream</h2>
          <div className="grid grid-cols-2 gap-6">
            <div>
              <div className="text-gray-400 text-sm mb-2">Mô tả</div>
              <p className="text-white">{livestream.description || 'Không có mô tả'}</p>
            </div>
            <div>
              <div className="text-gray-400 text-sm mb-2">Tags</div>
              <p className="text-white">{livestream.tags || 'Không có tags'}</p>
            </div>
            <div>
              <div className="text-gray-400 text-sm mb-2">Thời gian bắt đầu</div>
              <p className="text-white">{livestream.actualStartTime ? new Date(livestream.actualStartTime).toLocaleString() : 'Chưa bắt đầu'}</p>
            </div>
            <div>
              <div className="text-gray-400 text-sm mb-2">Stream Key</div>
              <p className="text-white font-mono text-xs break-all">{livestream.streamKey}</p>
            </div>
          </div>
        </div>

        {/* Actions */}
        <div className="flex gap-3">
          {livestream.status === 'live' && (
            <button className="px-6 py-2 bg-yellow-600 hover:bg-yellow-700 rounded text-white font-semibold">
              Tạm dừng (Pause)
            </button>
          )}
          {livestream.status === 'scheduled' && (
            <button className="px-6 py-2 bg-green-600 hover:bg-green-700 rounded text-white font-semibold">
              Bắt đầu (Start)
            </button>
          )}
          {livestream.status !== 'ended' && (
            <button className="px-6 py-2 bg-red-600 hover:bg-red-700 rounded text-white font-semibold">
              Kết thúc (End)
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default CreatorDashboard;

import { useEffect, useState, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';
import LivestreamPlayer from '../../../components/video/LivestreamPlayer';
import LivestreamChat from '../../../components/video/LivestreamChat';
import LivestreamReactions from '../../../components/video/LivestreamReactions';
import DonationPanel from '../../../components/DonationPanel';
import { useSignalRConnection } from '../../../hooks/useSignalRConnection';

const StudioLive = () => {
  const navigate = useNavigate();
  const { search } = useLocation();
  const params = new URLSearchParams(search);
  const idParam = params.get('id');
  const [livestream, setLivestream] = useState(null);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [thumbnailPreview, setThumbnailPreview] = useState('');
  const [tags, setTags] = useState('');
  const [isLive, setIsLive] = useState(false);
  const [streamTime, setStreamTime] = useState(0);
  const screenStreamRef = useRef(null);
  const timerIntervalRef = useRef(null);
  const videoRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const wsRef = useRef(null);
  const apiBase = '';

  // SignalR connection for reactions and chat
  const connRef = useSignalRConnection(livestream?.id, apiBase);

  const resolveCurrentChannel = async () => {
    try {
      const token = localStorage.getItem('token');
      if (!token) return null;

      const meRes = await axios.get('/api/channels/me', {
        headers: { Authorization: `Bearer ${token}` }
      });

      const resolvedChannelId = meRes?.data?.id;
      const resolvedHandle = meRes?.data?.handle;

      if (resolvedChannelId) {
        localStorage.setItem('channelId', resolvedChannelId);
      }
      if (resolvedHandle) {
        localStorage.setItem('handle', resolvedHandle);
      }

      return resolvedChannelId || null;
    } catch (err) {
      console.warn('Unable to resolve current channel via /api/channels/me:', err);
      return localStorage.getItem('channelId') || null;
    }
  };

  const handleThumbnailChange = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setThumbnailPreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const startScreenShare = async () => {
    if (!livestream || !livestream.id) return;

    try {
      let stream = null;
      const hasDisplayMedia = navigator.mediaDevices && typeof navigator.mediaDevices.getDisplayMedia === 'function';

      if (hasDisplayMedia) {
        try {
          stream = await navigator.mediaDevices.getDisplayMedia({
            video: { cursor: 'always' },
            audio: false
          });
        } catch (shareErr) {
          console.warn('User declined or browser blocked display sharing:', shareErr);
          const shouldContinue = window.confirm('Bạn chưa chia sẻ màn hình. Bạn vẫn muốn bắt đầu livestream bằng camera hoặc tiếp tục mà không chia sẻ màn hình?');
          if (!shouldContinue) return;
        }
      } else {
        console.warn('getDisplayMedia is not supported in this browser. Falling back to camera or continue without capture.');
        const shouldContinue = window.confirm('Trình duyệt của bạn không hỗ trợ chia sẻ màn hình. Bạn vẫn muốn bắt đầu livestream?');
        if (!shouldContinue) return;
      }

      if (!stream && navigator.mediaDevices && typeof navigator.mediaDevices.getUserMedia === 'function') {
        try {
          stream = await navigator.mediaDevices.getUserMedia({
            video: { facingMode: 'user' },
            audio: false
          });
        } catch (camErr) {
          console.warn('Camera fallback failed:', camErr);
        }
      }

      if (stream) {
        screenStreamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }

        const videoTrack = stream.getVideoTracks()[0];
        if (videoTrack) {
          videoTrack.onended = () => {
            stopScreenShare();
          };
        }

        // Initialize WebSocket connection to our Media Server Bridge
        const wsUrl = `ws://localhost:8001/stream?key=${livestream.streamKey}`;
        const ws = new WebSocket(wsUrl);
        wsRef.current = ws;

        ws.onopen = async () => {
          console.log('WebSocket connected. Starting MediaRecorder...');
          const options = { mimeType: 'video/webm;codecs=vp8,opus' };
          let recorder;
          try {
             recorder = new MediaRecorder(stream, options);
          } catch(e) {
             console.warn('vp8 not supported, falling back to default webm');
             recorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
          }
          
          mediaRecorderRef.current = recorder;

          recorder.ondataavailable = (e) => {
            if (e.data && e.data.size > 0 && ws.readyState === WebSocket.OPEN) {
              ws.send(e.data);
            }
          };

          recorder.start(1000); // Send chunks every 1 second

          setIsLive(true);
          setStreamTime(0);
          timerIntervalRef.current = setInterval(() => {
            setStreamTime((prev) => prev + 1);
          }, 1000);

          setLivestream({ ...livestream, status: 'live' });
        };
        
        ws.onerror = (e) => {
           console.error('WebSocket error:', e);
           alert('Không thể kết nối tới Media Server.');
        };
      }
    } catch (err) {
      console.error('Screen share error:', err);
      alert('Không thể bắt đầu livestream. Vui lòng thử lại hoặc bắt đầu bằng camera khác.');
    }
  };

  const stopScreenShare = async () => {
    if (!livestream || !livestream.id) return;
    try {
      // Dừng tất cả tracks
      if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach((track) => track.stop());
        screenStreamRef.current = null;
      }

      // Dừng timer
      if (timerIntervalRef.current) {
        clearInterval(timerIntervalRef.current);
        timerIntervalRef.current = null;
      }

      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
        mediaRecorderRef.current.stop();
        mediaRecorderRef.current = null;
      }

      if (wsRef.current) {
        wsRef.current.close();
        wsRef.current = null;
      }

      // We still call /end manually just in case webhook fails
      await axios.post(`${apiBase}/api/livestreams/${livestream.id}/end`, {}, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });

      setIsLive(false);
      alert('Đã kết thúc phát trực tiếp');
      navigate('/studio');
    } catch (err) {
      console.error('Stop screen share error:', err);
      alert('Lỗi khi kết thúc phát trực tiếp');
    }
  };

  const formatTime = (seconds) => {
    const hrs = Math.floor(seconds / 3600);
    const mins = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hrs.toString().padStart(2, '0')}:${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  useEffect(() => {
    if (videoRef.current && screenStreamRef.current) {
      videoRef.current.srcObject = screenStreamRef.current;
      videoRef.current.muted = true;
      videoRef.current.play().catch(() => {});
    }
  }, [isLive, livestream?.id]);

  useEffect(() => {
    if (idParam) {
      (async () => {
        try {
          const res = await axios.get(`${apiBase}/api/livestreams/${idParam}`);
          setLivestream(res.data);
        } catch (_err) {
          console.error(_err);
        }
      })();
    }

    // Cleanup: dừng stream khi component unmount
    return () => {
      if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach((track) => track.stop());
      }
      if (timerIntervalRef.current) {
        clearInterval(timerIntervalRef.current);
      }
      if (mediaRecorderRef.current && mediaRecorderRef.current.state !== 'inactive') {
        mediaRecorderRef.current.stop();
      }
      if (wsRef.current) {
        wsRef.current.close();
      }
    };
  }, [idParam]);

  const createStream = async () => {
    try {
      let channelId = await resolveCurrentChannel();

      if (!channelId) {
        const handle = localStorage.getItem('handle');
        if (handle) {
          try {
            const chRes = await axios.get(`/api/channels/${handle}`);
            channelId = chRes.data?.id;
            if (channelId) localStorage.setItem('channelId', channelId);
          } catch {
            // ignore and fall through
          }
        }
      }

      if (!channelId) {
        alert('Bạn chưa có kênh. Vui lòng tạo kênh trước.');
        return;
      }

      const streamKey = (window.crypto && window.crypto.randomUUID) ? window.crypto.randomUUID() : `sk_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
      const payload = {
        title: title || 'Live Stream',
        channelId,
        streamKey,
        description: description || '',
        thumbnailUrl: thumbnailPreview || '',
        hlsUrl: '',
        vodUrl: '',
        tags: tags || '',
        totalViews: 0,
        status: 'scheduled',
        scheduledStartTime: new Date().toISOString()
      };
      console.log('Creating livestream with payload:', payload);
      const res = await axios.post(`${apiBase}/api/livestreams`, payload, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      const created = res.data;
      navigate(`/studio/live?id=${created.id}`);
    } catch (err) {
      console.error(err);
      if (err?.response) {
        console.error('Server response:', err.response.status, err.response.data);
        alert(`Tạo livestream thất bại: ${JSON.stringify(err.response.data)}`);
      } else {
        alert('Tạo livestream thất bại');
      }
    }
  };

  const hasPlayableSource = Boolean(livestream?.hlsUrl || livestream?.vodUrl || livestream?.streamUrl || livestream?.playbackUrl);

  if (!idParam && !livestream) {
    return (
      <div className="p-6 max-w-4xl mx-auto">
        <h2 className="text-2xl font-bold text-white mb-6">Bắt đầu phát trực tiếp</h2>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-4">
            <div>
              <label className="block text-sm text-gray-300 mb-1">Tiêu đề</label>
              <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Nhập tiêu đề livestream" className="w-full p-2 rounded bg-[#111] border border-white/10 text-white placeholder-gray-500" />
            </div>
            <div>
              <label className="block text-sm text-gray-300 mb-1">Mô tả</label>
              <textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Nhập mô tả livestream (không bắt buộc)" className="w-full p-2 rounded bg-[#111] border border-white/10 text-white placeholder-gray-500 h-20 resize-none" />
            </div>
            <div>
              <label className="block text-sm text-gray-300 mb-1">Tags (phân cách bằng dấu phẩy)</label>
              <input value={tags} onChange={(e) => setTags(e.target.value)} placeholder="tag1, tag2, tag3" className="w-full p-2 rounded bg-[#111] border border-white/10 text-white placeholder-gray-500" />
            </div>
            <div className="flex gap-3 pt-2">
              <button onClick={createStream} className="px-4 py-2 bg-green-600 hover:bg-green-700 rounded text-white font-semibold">Tạo và bắt đầu</button>
              <button onClick={() => navigate(-1)} className="px-4 py-2 bg-white/5 hover:bg-white/10 rounded text-white">Hủy</button>
            </div>
          </div>

          <div className="lg:col-span-1">
            <div className="bg-[#0F0F0F] p-4 rounded">
              <label className="block text-sm text-gray-300 mb-2">Hình thumbnail</label>
              <div className="mb-3">
                <label className="block w-full p-4 border-2 border-dashed border-white/20 rounded cursor-pointer hover:border-white/40 transition text-center">
                  <div className="text-gray-400 text-sm">Chọn hình ảnh từ máy</div>
                  <input type="file" accept="image/*" onChange={handleThumbnailChange} className="hidden" />
                </label>
              </div>
              {thumbnailPreview && (
                <div className="w-full h-40 rounded overflow-hidden bg-black/50 flex items-center justify-center">
                  <img src={thumbnailPreview} alt="Preview" className="w-full h-full object-cover" />
                </div>
              )}
              {!thumbnailPreview && (
                <div className="w-full h-40 rounded bg-white/5 flex items-center justify-center text-gray-500 text-sm">
                  Chưa có hình preview
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6">
      {livestream && (
        <div className="mb-6 flex justify-between items-center bg-white/5 p-4 rounded">
          <div>
            <h2 className="text-2xl font-bold text-white mb-1">{livestream.title}</h2>
            <p className="text-sm text-gray-400">Trạng thái: {livestream.status}</p>
            {isLive && <p className="text-lg font-bold text-red-500 mt-2">🔴 LIVE {formatTime(streamTime)}</p>}
          </div>
          {!isLive && (
            <button
              onClick={startScreenShare}
              className="px-4 py-2 bg-red-600 hover:bg-red-700 rounded text-white font-semibold"
            >
              Bắt đầu chia sẻ màn hình
            </button>
          )}
          {isLive && (
            <button
              onClick={stopScreenShare}
              className="px-4 py-2 bg-red-700 hover:bg-red-800 rounded text-white font-semibold animate-pulse"
            >
              Kết thúc phát trực tiếp
            </button>
          )}
        </div>
      )}

      {livestream && !isLive && (
        <div className="mb-6 bg-[#141414] p-4 rounded border border-white/10">
          <h3 className="text-lg font-semibold text-white mb-3">Thông tin kết nối (Dùng cho OBS Studio)</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm text-gray-400 mb-1">Máy chủ tĩnh (RTMP URL)</label>
              <input readOnly value="rtmp://localhost:1935/live" className="w-full p-2 rounded bg-black border border-white/10 text-white font-mono text-sm" />
            </div>
            <div>
              <label className="block text-sm text-gray-400 mb-1">Khóa luồng (Stream Key)</label>
              <div className="flex gap-2">
                <input readOnly type="password" value={livestream.streamKey || ''} className="flex-1 p-2 rounded bg-black border border-white/10 text-white font-mono text-sm" />
                <button onClick={() => navigator.clipboard.writeText(livestream.streamKey)} className="px-3 py-2 bg-white/10 hover:bg-white/20 rounded text-white text-sm">Copy</button>
              </div>
            </div>
          </div>
          <p className="text-sm text-gray-400 mt-3">
            Bạn có thể dùng OBS Studio để phát trực tiếp thay vì trình duyệt. Nhập URL và Khóa luồng vào OBS, sau đó bấm "Start Streaming".
          </p>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          {isLive && livestream ? (
            <video
              ref={videoRef}
              autoPlay
              playsInline
              muted
              className="w-full h-80 bg-black rounded object-contain"
            />
          ) : livestream && hasPlayableSource ? (
            <LivestreamPlayer hlsUrl={livestream.hlsUrl || livestream.vodUrl || livestream.streamUrl || livestream.playbackUrl || ''} poster={livestream.thumbnailUrl} />
          ) : (
            <div className="w-full h-80 bg-black/60 rounded flex items-center justify-center text-center text-white px-6">
              {livestream ? 'Livestream chưa có luồng phát, đang chờ nguồn phát từ máy chủ.' : 'Đang tải...'}
            </div>
          )}
        </div>

        <div className="lg:col-span-1">
          <div className="bg-[#0F0F0F] p-4 rounded">
            <h3 className="text-lg font-bold text-white mb-3">Chat trực tiếp</h3>
            {livestream && livestream.id ? (
              <div className="space-y-4">
                <LivestreamChat livestreamId={livestream.id} apiBaseUrl={apiBase} userId={localStorage.getItem('userId')} />
                <LivestreamReactions livestreamId={livestream.id} connRef={connRef} />
                <DonationPanel livestreamId={livestream.id} connRef={connRef} />
              </div>
            ) : (
              <div className="text-gray-400 text-center py-8">Tạo livestream để bắt đầu chat</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default StudioLive;

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { UploadVideoForm } from './UploadVideoForm';

export default function StudioUpload({ isShortType = false }) {
  const navigate = useNavigate();
  const handle = localStorage.getItem('handle');

  const handleUploadSuccess = () => {
    if (handle) {
      navigate(`/c/${handle}`);
    } else {
      navigate('/');
    }
  };

  return (
    <div className="flex-1 overflow-y-auto bg-[#0F0F0F] p-8">
      <div className="max-w-5xl mx-auto">
        <h1 className="text-2xl font-bold text-white mb-6">
          {isShortType ? 'Tạo video ngắn' : 'Tạo video mới'}
        </h1>
        <UploadVideoForm 
          onUploadSuccess={handleUploadSuccess} 
          isShortType={isShortType} 
        />
      </div>
    </div>
  );
}

