                      {isShort && (
                        <div className="absolute bottom-2 left-2 flex items-center gap-1 bg-black/70 backdrop-blur-sm text-white text-[10px] font-bold px-1.5 py-0.5 rounded">
                          <Zap className="w-3 h-3 fill-white" /> SHORTS
